sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float2 center;
uniform float amountX;
uniform float amountY;
uniform float radius;
uniform float feather;
uniform float curve;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float2 ctr = center * size;
    float2 d = coord - ctr;
    float rr = radius * length(size) * 0.5;
    float mask = pow(1.0 - smoothstep(rr * (1.0 - feather), rr, length(d)), curve);
    float2 amt = max(float2(1.0) + float2(amountX, amountY) * mask, float2(0.1));
    return fin(c, tex(ctr + d / amt), opacity);
}
